         self.blocks.clone()
     }

     pub fn metadata(&self) -> Option<String> {
         self.metadata.clone()
     }

     pub fn top_block(&mut self) -> &mut DocumentBlock {
         self.blocks_stack.last_mut().unwrap_or_else(|| {
             panic!(
                 "parse markdown:\n{}",
