#[test]
fn bare_frontmatter_preserves_yaml_sequence_for_meta_filter() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Foo
            depends:
              - foo
              - bar

            # Body
            "}),
        bare_options(),
        None,
    );

    let metadata = graph
        .get_metadata(&liwe::model::Key::name("1"))
        .expect("metadata should be present");
    let parsed: serde_yaml::Value =
        serde_yaml::from_str(metadata).expect("metadata should be valid YAML");
    let depends = parsed.get("depends").expect("depends key should exist");
    assert!(
        depends.is_sequence(),
        "depends should be a sequence, got: {:?}",
        depends
    );

    let finder = DocumentFinder::new(&graph);
    let options = FindOptions {
        metadata_filters: vec![("depends".to_string(), "foo".to_string())],
        ..Default::default()
    };
    let output = finder.find(&options);
    assert_eq!(
        output.results.len(),
        1,
        "expected --meta depends=foo to match the bare-frontmatter document"
    );
}

